option.value:
:root {
  --dark: #303079;
  --accent: #4992CF;
  --white: #fff;
  --soft: #eef4fb;
  --text: #22224d;
  --radius: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: "Segoe UI", system-ui, -apple-system, Roboto, sans-serif;
  color: var(--text);
  background: var(--white);
  line-height: 1.65;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
  border-radius: var(--radius);
}

a {
  color: var(--accent);
}

a:focus-visible,
button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

h1,
h2,
h3 {
  color: var(--dark);
  line-height: 1.2;
}

h1 {
  font-size: clamp(2rem, 5vw, 3.2rem);
}

h2 {
  font-size: 1.9rem;
  margin-bottom: 0.5rem;
}

h3 {
  font-size: 1.15rem;
  margin-bottom: 0.4rem;
}

.container {
  width: min(1100px, 92%);
  margin-inline: auto;
}

section {
  padding: 4rem 0;
}

.lead {
  max-width: 60ch;
  margin-bottom: 2rem;
  opacity: 0.85;
}

.alt {
  background: var(--soft);
}

/* Header / nav */

.site-header {
  background: var(--dark);
  position: sticky;
  top: 0;
  z-index: 10;
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.9rem 0;
}

.brand {
  color: var(--white);
  font-weight: 700;
  font-size: 1.2rem;
  text-decoration: none;
}

.nav-list {
  display: flex;
  gap: 1.5rem;
  list-style: none;
  padding: 0;
  align-items: center;
}

.nav-list a {
  color: var(--white);
  text-decoration: none;
  padding: 0.3rem 0;
  border-bottom: 2px solid transparent;
}

.nav-list a:hover,
.nav-list a[aria-current="page"] {
  color: var(--accent);
  border-color: var(--accent);
}

.nav-list .lang {
  border: 1px solid var(--accent);
  border-radius: 999px;
  padding: 0.15rem 0.8rem;
  font-size: 0.85rem;
}

.nav-list .lang b {
  color: var(--accent);
  font-weight: 700;
}

.nav-toggle {
  display: none;
  background: none;
  border: 0;
  cursor: pointer;
  padding: 0.4rem;
}

.nav-toggle span {
  display: block;
  width: 26px;
  height: 3px;
  background: var(--white);
  margin: 5px 0;
  border-radius: 2px;
}

/* Buttons */

.btn {
  display: inline-block;
  background: var(--accent);
  color: var(--white);
  padding: 0.75rem 1.6rem;
  border-radius: 999px;
  text-decoration: none;
  font-weight: 600;
  transition: background 0.2s;
}

.btn:hover {
  background: var(--white);
  color: var(--dark);
}

.btn.outline {
  background: transparent;
  border: 2px solid var(--white);
  color: var(--white);
}

.btn.outline:hover {
  background: var(--white);
  color: var(--dark);
}

/* Hero */

.hero {
  background: var(--dark);
  color: var(--white);
  padding: 4rem 0;
}

.hero h1 {
  color: var(--white);
}

.hero-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.hero img {
  width: 100%;
  height: 420px;
  object-fit: cover;
}

.hero p {
  margin: 1rem 0 1.8rem;
  font-size: 1.15rem;
  max-width: 44ch;
}

.hero .btn + .btn {
  margin-left: 0.6rem;
}

.page-hero {
  background: var(--dark);
  color: var(--white);
  padding: 3rem 0;
}

.page-hero h1 {
  color: var(--white);
}

/* Stats bar */

.stats {
  background: var(--accent);
  color: var(--white);
  padding: 1.6rem 0;
}

.stats ul {
  list-style: none;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  text-align: center;
  gap: 1rem;
}

.stats strong {
  display: block;
  font-size: 2rem;
}

/* Cards & grids */

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
}

.card {
  background: var(--white);
  border: 1px solid #d9e5f3;
  border-radius: var(--radius);
  padding: 1.4rem;
  box-shadow: 0 4px 14px rgba(48, 48, 121, 0.07);
}

.card img {
  margin: -0.4rem 0 1rem;
  width: 100%;
  height: 170px;
  object-fit: cover;
}

.card ul {
  padding-left: 1.2rem;
}

.price {
  color: var(--accent);
  font-weight: 700;
  white-space: nowrap;
}

.item {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
}

.menu-cat {
  margin-bottom: 3rem;
}

.menu-cat h2 {
  border-bottom: 3px solid var(--accent);
  display: inline-block;
  margin-bottom: 1.2rem;
}

.split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2.5rem;
  align-items: center;
}

.contact-list {
  list-style: none;
  padding: 0;
}

.contact-list li {
  margin-bottom: 0.7rem;
}

table {
  border-collapse: collapse;
  width: 100%;
}

td {
  padding: 0.5rem 0;
  border-bottom: 1px solid #d9e5f3;
}

td:last-child {
  text-align: right;
  font-weight: 600;
}

.map iframe {
  width: 100%;
  height: 340px;
  border: 0;
  border-radius: var(--radius);
}

/* Footer */

.site-footer {
  background: var(--dark);
  color: var(--white);
  padding: 3rem 0 1.5rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
}

.site-footer h3 {
  color: var(--white);
}

.site-footer a {
  color: var(--white);
  text-decoration: none;
}

.site-footer a:hover {
  color: var(--accent);
}

.site-footer ul {
  list-style: none;
  padding: 0;
}

.copy {
  margin-top: 2rem;
  padding-top: 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
  font-size: 0.9rem;
  opacity: 0.8;
}

/* Mobile */

@media (max-width: 760px) {
  .nav-toggle {
    display: block;
  }

  .nav-list {
    display: none;
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    background: var(--dark);
    flex-direction: column;
    align-items: flex-start;
    padding: 1rem 4%;
    gap: 0.8rem;
  }

  .nav-list.open {
    display: flex;
  }

  .hero-grid,
  .split {
    grid-template-columns: 1fr;
  }

  .stats ul {
    grid-template-columns: 1fr;
  }

  section {
    padding: 3rem 0;
  }
}

